// Pseudo-random number generator (from Book of Shaders)
float rand(vec2 co){
    return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    uv -= 0.5;
    uv.x *= iResolution.x/iResolution.y;

    float time = iTime * 0.1;

    // Background color
    vec3 backgroundColor = vec3(0.02, 0.03, 0.05);
    fragColor = vec4(backgroundColor, 1.0);

    // Star density and brightness control
    float starDensity = 0.002;
    float starBrightness = 1.5;

    // Random number generation based on pixel coordinates
    vec2 seed = uv * vec2(1000.0, 1000.0);
    float randVal = fract(sin(dot(seed, vec2(12.9898, 78.233))) * 43758.5453);

    // Star positions and sizes
    if (randVal < starDensity) {
        float size = mix(1.0, 3.0, fract(randVal * 1000.0)); // Varying sizes
        vec2 starPos = uv + vec2(rand(seed*10.0),rand(seed*10.0)) * 0.005; //slight position offset for more natural distribution
        float dist = length(starPos - uv);
        float starIntensity = smoothstep(0.005, 0.0, dist);

        // Star color variations (slightly warm)
        vec3 starColor = mix(vec3(1.0, 0.9, 0.8), vec3(1.0, 0.95, 0.9), fract(randVal * 500.0));

        //Twinkling effect
        float twinkle = sin(time* (randVal*10.0+1.0))*0.5+0.5;
        starIntensity *= twinkle;

        fragColor.rgb += starColor * starIntensity * size * starBrightness;

    }

    // Larger, fainter stars
    starDensity *= 0.1;
    if (randVal < starDensity) {
        float size = mix(2.0, 5.0, fract(randVal * 200.0));
        vec2 starPos = uv + vec2(rand(seed*5.0),rand(seed*5.0)) * 0.01;
        float dist = length(starPos - uv);
        float starIntensity = smoothstep(0.01, 0.0, dist);
        fragColor.rgb += vec3(0.8, 0.85, 1.0) * starIntensity * size * (starBrightness * 0.3);
    }
}
